class Solution {
public:
    long long countValidSubstrings(string s) {
        long long ans = 0;
        int lastA = -1;      // latest position of 'a'
        int bestAB = -1;     // largest start index of any "ab" seen so far
        int bestABC = -1;    // largest start index of any "abc" seen so far

        for (int i = 0; i < (int)s.size(); ++i) {
            char ch = s[i];
            if (ch == 'a') {
                lastA = i;
            } else if (ch == 'b') {
                if (lastA != -1) {
                    bestAB = max(bestAB, lastA);
                }
            } else { // ch == 'c'
                if (bestAB != -1) {
                    bestABC = max(bestABC, bestAB);
                }
            }
            ans += i - bestABC; // all substrings ending at i that start after bestABC are valid
        }
        return ans;
    }
};
